INSERT INTO site_settings (setting_key, setting_value, setting_type, setting_label, group_name) VALUES
('college_name', 'Kashmir College of Engineering & Technology', 'text', 'College Full Name', 'general'),
('college_short_name', 'KCET', 'text', 'Short Acronym', 'general'),
('tagline', 'Engineering Futures, Innovating Today.', 'text', 'Tagline', 'general'),
('address', 'Ranbirgarh, Srinagar, Jammu and Kashmir 190001, India', 'textarea', 'Campus Address', 'contact'),
('phone_primary', '+91 88994 12793', 'text', 'Primary Phone', 'contact'),
('phone_secondary', '+91 194 2490000', 'text', 'Secondary Phone', 'contact'),
('email_primary', 'info@kcet.edu.in', 'email', 'Primary Email', 'contact'),
('email_secondary', 'kcetsrinagar@gmail.com', 'email', 'Alternate Email', 'contact'),
('office_hours', 'Monday – Saturday: 9:00 AM – 5:00 PM', 'text', 'Office Hours', 'contact'),
('campus_area', '100+ Kanals', 'text', 'Campus Size', 'overview'),
('approved_intake', '360+ Seats', 'text', 'Total Intake', 'overview'),
('hero_title', 'Engineering Futures, Innovating Today in the Heart of Kashmir', 'text', 'Hero Headline', 'homepage'),
('hero_subtitle', 'Join Kashmir College of Engineering & Technology (KCET) at our lush 100+ kanal green campus in Ranbirgarh, Srinagar. State-of-the-art labs, visionary faculty, and industry-aligned B.Tech programmes.', 'textarea', 'Hero Subtitle', 'homepage'),
('hero_notice_ticker', 'Admissions Open for B.Tech Batch 2026-27 | Lateral Entry (3rd Sem) Admissions Open | Campus Placement Boot Camp scheduled soon.', 'textarea', 'Homepage Marquee/Ticker', 'homepage'),
('admission_modal_enabled', '1', 'text', 'Show Admission Announcement Modal', 'homepage'),
('admission_modal_title', 'Admissions Open 2026-27', 'text', 'Modal Announcement Title', 'homepage'),
('admission_modal_body', 'Applications are actively invited for 4-Year B.Tech and 3-Year Lateral Entry programmes in AI, Computer Engineering, Civil, IT, and ECE. Merit-based scholarships available.', 'textarea', 'Modal Announcement Body', 'homepage'),
('youtube_tour_url', 'https://www.youtube.com/embed/Oog3g2U-UbM', 'url', 'Campus Tour Video Embed URL', 'homepage'),
('chairman_name', 'Er. Bashir Ahmad', 'text', 'Chairman Full Name', 'leadership'),
('chairman_designation', 'Chairman, Kashmir Educational Society', 'text', 'Chairman Designation', 'leadership'),
('chairman_photo', 'assets/images/faculty-hod-cse.jpg', 'text', 'Chairman Photo Path', 'leadership'),
('chairman_quote', 'Our mission is to cultivate visionary engineering leaders who will architect the future of Jammu & Kashmir and contribute meaningfully to global innovation.', 'textarea', 'Chairman Inspiring Quote', 'leadership'),
('chairman_message', 'Kashmir College of Engineering & Technology was established with a singular vision: to democratize world-class technical education in the Kashmir valley. Over the past two decades, we have continuously expanded our academic horizons, investing in modern high-performance computational infrastructure, advanced testing laboratories, and distinguished academic mentorship. We invite every student to build their engineering aspirations with us.', 'textarea', 'Chairman Full Address', 'leadership'),
('director_name', 'Er. Mushtaq Ahmad Mir', 'text', 'Director Full Name', 'leadership'),
('director_designation', 'Managing Director & Trustee', 'text', 'Director Designation', 'leadership'),
('director_photo', 'assets/images/faculty-hod-ai.jpg', 'text', 'Director Photo Path', 'leadership'),
('director_quote', 'Our serene 100+ kanal green campus in Ranbirgarh was envisioned as a sanctuary of scholarship, where students pursue rigorous engineering education without distraction.', 'textarea', 'Director Inspiring Quote', 'leadership'),
('director_message', 'At KCET, we bridge classroom theoretical foundations with hands-on industrial and laboratory exposure. Our students are trained to be agile, ethical, and inventive problem solvers. With active AICTE approval and University of Kashmir affiliation, we ensure our graduates excel in both competitive industrial placements and premier postgraduate research institutions worldwide.', 'textarea', 'Director Full Address', 'leadership'),
('principal_name', 'Dr. Syed Jalal Ahmad', 'text', 'Principal Full Name', 'leadership'),
('principal_designation', 'Principal & Professor of Engineering', 'text', 'Principal Designation', 'leadership'),
('principal_qualifications', 'Ph.D. (IIT Delhi), M.Tech, B.E.', 'text', 'Principal Qualifications', 'leadership'),
('principal_photo', 'assets/images/principal-portrait.svg', 'text', 'Principal Photo Path', 'leadership'),
('principal_quote', 'Engineering education at KCET is deeply grounded in hands-on scientific enquiry, ethical problem-solving, and outcome-based pedagogical rigor. We prepare engineers not merely for examinations, but to solve real infrastructure and technological challenges of Jammu & Kashmir and the world.', 'textarea', 'Principal Inspiring Quote', 'leadership'),
('principal_message', 'Since its inception, Kashmir College of Engineering & Technology has stood as a beacon of high-quality technical education in Srinagar. Situated across a lush 100+ kanal green campus, our institution provides an ideal environment where academic curiosity meets state-of-the-art laboratory experimentation. With approval from AICTE and affiliation to the prestigious University of Kashmir, our curriculum continually integrates modern computational frameworks, artificial intelligence paradigms, sustainable civil designs, and advanced electronics.', 'textarea', 'Principal Full Address', 'leadership');
INSERT INTO departments (id, name, slug, code, hod_name, hod_designation, hod_photo, hod_message, vision, mission, overview, labs_info, display_order, is_active) VALUES
(1, 'Department of Computer Engineering', 'computer-engineering', 'CE', 'Er. Farooq Ahmad', 'Associate Professor & HOD', 'assets/images/faculty-hod-cse.jpg', 'Welcome to the Department of Computer Engineering. Our mission is to produce engineers equipped with strong software, algorithmic, and analytical competencies to solve complex digital challenges.', 'To emerge as a premier centre of education and research in Computer Engineering, cultivating innovation, leadership, and ethical technical practice.', 'Deliver robust curriculum in computer science principles and modern technologies; foster experiential learning through industry-oriented projects; uphold research ethics.', 'The Department of Computer Engineering offers an in-depth curriculum spanning data structures, algorithms, operating systems, cloud architecture, cybersecurity, and full-stack software development.', 'Modern Computing Labs with 120+ high-end workstations, Linux Lab, Software Engineering Studio, and High-Speed Fiber Internet.', 1, 1),
(2, 'Department of Artificial Intelligence Engineering', 'artificial-intelligence-engineering', 'AIE', 'Dr. Shabir Hussain', 'Professor & HOD', 'assets/images/faculty-hod-ai.jpg', 'AI is transforming the modern industrial landscape. At KCET, we equip our students with state-of-the-art machine learning, deep learning, NLP, and intelligent robotics toolsets.', 'To be recognized as a leading department in Artificial Intelligence, advancing intelligent systems and data-driven solutions for societal benefit.', 'Impart specialized education in machine learning, neural networks, and automated systems; provide hands-on experience on GPU-accelerated computing infrastructure.', 'The Department of Artificial Intelligence Engineering focuses on machine learning, computer vision, natural language processing, intelligent robotics, and predictive analytics.', 'NVIDIA GPU Accelerated AI Lab, Deep Learning Simulation Centre, Python & Data Science Sandbox.', 2, 1),
(3, 'Department of Civil Engineering', 'civil-engineering', 'civil-engineering', 'Er. Tariq Masood', 'Associate Professor & HOD', 'assets/images/faculty-hod-civil.jpg', 'Civil Engineering is the backbone of regional infrastructure. Our department blends rigorous structural theory with active field surveys and sustainable geotechnical practices.', 'To produce competent civil engineers capable of designing resilient, earthquake-resistant, and sustainable infrastructure in challenging mountainous terrains.', 'Deliver comprehensive training in structural analysis, survey, geotechnical and transportation engineering; emphasize environmental conservation and hazard resilience.', 'The Department of Civil Engineering is known for practical survey expeditions, concrete technology testing, and soil mechanics experiments suited for Himalayan geology.', 'Concrete Technology & Materials Lab, Soil Mechanics Lab, Total Station Survey Lab, Environmental Engineering Lab, Fluid Mechanics Lab.', 3, 1),
(4, 'Department of Information Technology Engineering', 'information-technology-engineering', 'ITE', 'Er. Mushtaq Rather', 'Associate Professor & HOD', 'assets/images/faculty-hod-it.jpg', 'Information Technology drives modern enterprises. We prepare students for networking, cloud security, web architectures, and scalable IT infrastructure management.', 'To lead in IT education by cultivating future-ready engineers skilled in enterprise systems, cyber defenses, and intelligent information networks.', 'Provide cutting-edge knowledge in network administration, database architecture, and mobile platforms; foster entrepreneurial and problem-solving mindsets.', 'The Department of Information Technology offers specialised courses in cloud computing, network architecture, information security, and enterprise database management.', 'Enterprise Networking Lab, Database Systems Lab, Web & Mobile Application Development Lab.', 4, 1),
(5, 'Department of Electronics and Communication Engineering', 'electronics-and-communication-engineering', 'ECE', 'Dr. Adil Nisar', 'Professor & HOD', 'assets/images/faculty-hod-ece.jpg', 'Electronics and Communication powers telecom, IoT, and embedded smart systems. Our labs provide real-world exposure to circuit design, VLSI, and signal processing.', 'To pioneer education and research in electronics, signal processing, and communication technologies that connect communities and industries.', 'Provide foundational and advanced knowledge in microcontrollers, VLSI, wireless networks, and embedded systems; inspire innovations in IoT and digital communication.', 'The Department of ECE offers training across analog and digital circuits, microwave systems, microprocessors, IoT sensor networks, and VLSI design.', 'Analog & Digital Electronics Lab, Microprocessor & Microcontroller Lab, Communication Systems Lab, VLSI Design Lab, IoT Innovation Hub.', 5, 1),
(6, 'Department of Applied Sciences & Humanities', 'applied-sciences-and-humanities', 'ASH', 'Dr. Naseer Ahmad', 'Professor & HOD', 'assets/images/faculty-hod-ash.jpg', 'Applied Sciences and Humanities form the vital foundational bedrock for all engineering disciplines. We foster analytical thought, mathematical rigor, and professional communication skills.', 'To provide foundational excellence in basic sciences, mathematics, and human values that empower future engineers.', 'Strengthen conceptual clarity in Engineering Physics, Chemistry, and Applied Mathematics; hone communication and ethical reasoning skills.', 'The Department teaches foundational first-year courses across all B.Tech branches, ensuring every engineering student builds strong quantitative and analytical fundamentals.', 'Engineering Physics Lab, Engineering Chemistry Lab, Language & Communication Skills Lab.', 6, 1);
INSERT INTO programmes (id, department_id, name, slug, degree_type, duration, intake, eligibility, fee_info, syllabus_file, summary, description, career_prospects, is_featured, is_admissions_open, is_active, display_order) VALUES
(1, 2, 'B.Tech in Artificial Intelligence Engineering', 'b-tech-artificial-intelligence-engineering', 'B.Tech', '4 Years (8 Semesters)', '60 Seats (Needs Verification)', '10+2 with Physics, Mathematics, and Chemistry/Computer Science with minimum 45% marks (40% for reserved categories). Lateral entry: 3-Year Engineering Diploma in relevant branch.', 'Competitive fee structure approved by state regulatory authorities. Fee concessions and merit scholarships available. Please contact admissions office for current schedule.', 'assets/files/syllabus-ai.pdf', 'Specialized 4-year degree exploring machine learning, neural networks, computer vision, natural language processing, and autonomous systems.', 'The B.Tech in Artificial Intelligence Engineering at KCET offers an intensive immersion into data intelligence and autonomous technologies. Students master Python, machine learning algorithms, deep neural architectures, robotics, and cloud AI deployment. The curriculum is reinforced by hands-on lab work in our dedicated AI and GPU laboratory.', 'AI Engineer, Machine Learning Specialist, Data Scientist, Computer Vision Engineer, NLP Developer, Robotics Software Engineer.', 1, 1, 1, 1),
(2, 1, 'B.Tech in Computer Engineering', 'b-tech-computer-engineering', 'B.Tech', '4 Years (8 Semesters)', '120 Seats (Needs Verification)', '10+2 with Physics, Mathematics, and Chemistry/Computer Science with minimum 45% marks. Lateral entry eligible for diploma holders.', 'Transparent, affordable annual fee approved by college governing council. Installment options and merit waivers available.', 'assets/files/syllabus-ce.pdf', 'Comprehensive computer science programme covering software architecture, data structures, algorithms, databases, web systems, and cybersecurity.', 'The B.Tech in Computer Engineering provides an all-inclusive foundation in computing systems, algorithmic analysis, software engineering, and operating systems. KCET students participate in hackathons, collaborative coding sprints, and industry internships that build industry-ready development competence.', 'Software Development Engineer (SDE), Full-Stack Web Developer, Systems Architect, Cloud Engineer, Database Administrator, Cybersecurity Analyst.', 1, 1, 1, 2),
(3, 3, 'B.Tech in Civil Engineering', 'b-tech-civil-engineering', 'B.Tech', '4 Years (8 Semesters)', '60 Seats (Needs Verification)', '10+2 with Physics, Mathematics, and Chemistry with at least 45% marks. 3-Year Diploma in Civil Engineering for Lateral Entry into 3rd semester.', 'Standard engineering fee schedule. Inquire at admissions desk for current session details.', 'assets/files/syllabus-civil.pdf', 'Classic engineering discipline focusing on structural design, geotechnical testing, surveying, highway engineering, and sustainable construction.', 'The B.Tech in Civil Engineering at KCET blends classroom theory with extensive field surveys, concrete testing, and environmental engineering studies. The curriculum emphasizes sustainable building materials, seismic design considerations for mountainous regions, and modern Total Station surveying.', 'Structural Engineer, Geotechnical Consultant, Site Engineer, Project Manager, Urban Infrastructure Planner, Quality Control Engineer.', 1, 1, 1, 3),
(4, 4, 'B.Tech in Information Technology Engineering', 'b-tech-information-technology-engineering', 'B.Tech', '4 Years (8 Semesters)', '60 Seats (Needs Verification)', '10+2 with Physics, Mathematics, and Chemistry/Computer Science with minimum 45% marks. Diploma in IT/CSE eligible for lateral entry.', 'Conforming to university guidelines. Contact admissions desk for scholarship breakdown.', 'assets/files/syllabus-it.pdf', 'Career-oriented programme spanning network security, enterprise cloud services, database management, and web application systems.', 'Information Technology powers modern digital businesses. KCET’s B.Tech IT programme equips students with rigorous knowledge of networking protocols, distributed databases, cloud systems, web services, and cybersecurity defense strategies.', 'Network Architect, IT Systems Administrator, Information Security Consultant, DevOps Engineer, Cloud Solutions Architect.', 1, 1, 1, 4),
(5, 5, 'B.Tech in Electronics and Communication Engineering', 'b-tech-electronics-and-communication-engineering', 'B.Tech', '4 Years (8 Semesters)', '60 Seats (Needs Verification)', '10+2 with Physics, Mathematics, and Chemistry/Electronics with minimum 45% marks. Diploma in ECE eligible for lateral entry.', 'Reasonable fee structure with merit allowances. Contact the accounts and admissions desk for exact fee schedule.', 'assets/files/syllabus-ece.pdf', 'Focuses on circuit design, embedded microcontrollers, IoT sensor systems, wireless telecommunications, and digital signal processing.', 'The B.Tech in Electronics and Communication Engineering prepares students to create the next generation of smart hardware, IoT sensors, wireless communication devices, and embedded systems. With modern signal processing and VLSI simulation tools, KCET graduates are well-prepared for telecommunication, electronics manufacturing, and automation sectors.', 'Embedded Systems Engineer, IoT Solutions Architect, Telecom Specialist, VLSI Design Engineer, Hardware Testing Engineer.', 1, 1, 1, 5);
INSERT INTO faculty (id, department_id, name, slug, designation, qualification, specialization, email, phone, bio, photo, display_order, is_active) VALUES
(1, 1, 'Er. Farooq Ahmad', 'er-farooq-ahmad', 'Associate Professor & HOD', 'M.Tech (CSE), B.Tech (CSE)', 'Data Structures, Cloud Computing, Operating Systems', 'farooq.ahmad@kcet.edu.in', NULL, 'Er. Farooq Ahmad has over 14 years of teaching and academic administration experience. His core interests include distributed systems, cloud architectures, and scalable algorithms.', 'assets/images/faculty-1.jpg', 1, 1),
(2, 2, 'Dr. Shabir Hussain', 'dr-shabir-hussain', 'Professor & HOD', 'Ph.D. in Computer Science (AI & ML), M.Tech', 'Machine Learning, Neural Networks, Computer Vision', 'shabir.hussain@kcet.edu.in', NULL, 'Dr. Shabir Hussain has published numerous papers in international journals on deep learning and automated feature extraction. He oversees the GPU-accelerated AI lab at KCET.', 'assets/images/faculty-2.jpg', 2, 1),
(3, 3, 'Er. Tariq Masood', 'er-tariq-masood', 'Associate Professor & HOD', 'M.Tech (Structural Engineering), B.Tech', 'Seismic Design, Concrete Structures, Highway Engineering', 'tariq.masood@kcet.edu.in', NULL, 'Er. Tariq Masood brings extensive field engineering and consultancy experience in seismic-resistant structural design in the Kashmir valley.', 'assets/images/faculty-3.jpg', 3, 1),
(4, 4, 'Er. Mushtaq Rather', 'er-mushtaq-rather', 'Associate Professor & HOD', 'M.Tech (IT), B.E. (Computer Science)', 'Network Security, Cloud Computing, Web Technologies', 'mushtaq.rather@kcet.edu.in', NULL, 'Er. Mushtaq Rather specializes in enterprise network security, cloud infrastructures, and digital forensics. He coordinates technical boot camps at KCET.', 'assets/images/faculty-4.jpg', 4, 1),
(5, 5, 'Dr. Adil Nisar', 'dr-adil-nisar', 'Professor & HOD', 'Ph.D. (Electronics Engineering), M.Tech', 'VLSI Design, Embedded IoT Systems, Digital Signal Processing', 'adil.nisar@kcet.edu.in', NULL, 'Dr. Adil Nisar has authored over 20 research publications on low-power VLSI design and microstrip antenna systems. He mentors student innovation teams.', 'assets/images/faculty-5.jpg', 5, 1),
(6, 6, 'Dr. Naseer Ahmad', 'dr-naseer-ahmad', 'Professor & HOD', 'Ph.D. in Applied Mathematics, M.Sc', 'Numerical Analysis, Differential Equations, Applied Statistics', 'naseer.ahmad@kcet.edu.in', NULL, 'Dr. Naseer Ahmad has taught advanced engineering mathematics and numerical techniques for over 18 years, inspiring foundational analytical competence.', 'assets/images/faculty-6.jpg', 6, 1),
(7, 1, 'Er. Zahoor Peerzada', 'er-zahoor-peerzada', 'Assistant Professor', 'M.Tech (Computer Engineering)', 'Database Systems, Full-Stack Development, Cyber Security', 'zahoor.peerzada@kcet.edu.in', NULL, 'Er. Zahoor coordinates student project development and coding workshops at KCET.', 'assets/images/faculty-7.jpg', 7, 1),
(8, 3, 'Er. Saima Jan', 'er-saima-jan', 'Assistant Professor', 'M.Tech (Geotechnical Engineering)', 'Soil Mechanics, Environmental Engineering, Hydrology', 'saima.jan@kcet.edu.in', NULL, 'Er. Saima supervises soil testing and geotechnical survey practices in the Department of Civil Engineering.', 'assets/images/faculty-8.jpg', 8, 1);
INSERT INTO facilities (id, title, slug, badge, summary, description, image, display_order, is_active) VALUES
(1, 'Spacious Library & Digital Resource Centre', 'spacious-library', 'Academic Hub', 'Extensive collection of engineering volumes, international journals, reference books, and high-speed digital research terminals.', 'The central library of KCET is an expansive sanctuary for academic inquiry. Stocked with thousands of textbooks, standard references, national and international journals, and digital IEEE/DELNET access terminals, it caters comprehensively to students and faculty researchers. Spacious reading halls ensure an ideal atmosphere for quiet study and intellectual growth.', 'assets/images/facility-auditorium-hall.jpg', 1, 1),
(2, 'Canteen & Cafeteria', 'canteen-and-cafeteria', 'Student Life', 'Hygienic campus cafeteria serving fresh meals, snacks, Kashmiri tea, and coffee in a comfortable social space.', 'The college cafeteria is a vibrant student hub offering nutritious, freshly cooked meals, hot beverages, and refreshments under strict hygiene protocols. It provides a welcoming social area where students and faculty recharge and engage in informal discussions.', 'assets/images/student-life-campus.jpg', 2, 1),
(3, 'Transport Facility', 'transport-facility', 'Campus Mobility', 'Extensive fleet of college buses operating across Srinagar and major neighbouring districts.', 'KCET operates a dependable and safe fleet of college buses covering key routes across Srinagar, Budgam, Ganderbal, and adjacent areas. Ensuring punctual transit for both students and faculty members, the fleet is supervised with dedicated transport staff.', 'assets/images/campus-front-facade.jpg', 3, 1),
(4, 'Dedicated 100 Mbps Internet & Campus Wi-Fi', 'dedicated-100-mbps-internet', 'High-Speed Connectivity', 'High-capacity optical fiber internet providing seamless connectivity across classrooms, laboratories, and the central library.', 'The campus is linked by an enterprise 100 Mbps dedicated fiber-optic internet connection, providing seamless wireless and wired connectivity across laboratories, academic blocks, the digital library, and administrative offices for research, coursework, and online certifications.', 'assets/images/lab-computing-ai.jpg', 4, 1),
(5, 'Multipurpose Hall & Auditorium', 'multipurpose-hall', 'Events & Culture', 'Well-equipped auditorium for technical symposia, orientation ceremonies, guest lectures, and cultural events.', 'Equipped with modern acoustic architecture, high-definition projection systems, and stage lighting, the Multipurpose Hall accommodates large student gatherings, national seminars, guest lectures by eminent scientists, and college cultural activities.', 'assets/images/facility-auditorium-hall.jpg', 5, 1),
(6, 'Training & Placement Cell', 'training-and-placement-cell', 'Career Development', 'Dedicated cell providing interview grooming, resume coaching, technical aptitude sessions, and placement drives.', 'The Training & Placement Cell bridges academia and corporate industry. Conducting regular soft-skill workshops, mock technical interviews, aptitude training, and arranging on-campus/off-campus recruitment opportunities, the cell empowers students to secure high-trajectory engineering careers.', 'assets/images/classroom-lecture-theatre.jpg', 6, 1),
(7, 'Medical & First-Aid Room', 'medical-room', 'Health & Wellness', 'Dedicated medical room with first-aid kits, emergency beds, patient monitoring tools, and qualified health attendants.', 'Student and staff health is paramount. The campus medical centre is equipped with essential medical supplies, emergency oxygen, observation beds, and regular doctor visits, with fast access to regional medical facilities when required.', 'assets/images/campus-main-block.jpg', 7, 1),
(8, 'Advanced Computer Centre', 'computer-centre', 'Technical Infrastructure', 'State-of-the-art workstations with latest operating systems, coding IDEs, simulation packages, and CAD tools.', 'The central computer centre features cutting-edge desktop workstations configured with Linux, Windows, development compilers, simulation software (MATLAB, AutoCAD, ANSYS), and high-speed local networking for practical laboratory coursework and hackathons.', 'assets/images/lab-computing-ai.jpg', 8, 1),
(9, 'Fire Safety & Smoke Detection', 'fire-safety-and-smoke-detectors', 'Campus Safety', 'Comprehensive fire-fighting equipment, smoke detectors, safety alarms, and clearly marked evacuation paths.', 'The institution places strict emphasis on physical safety, with smoke alarms, certified fire extinguishers, emergency hydrants, clear signage, and periodic evacuation drills conducted to train campus occupants.', 'assets/images/facility-testing-lab.jpg', 9, 1),
(10, '24/7 CCTV Monitoring & Security', '24-7-cctv-monitoring', 'Campus Security', 'Comprehensive camera coverage and round-the-clock trained security personnel across the 100+ kanal campus.', 'KCET maintains high security standards through comprehensive 24/7 CCTV surveillance covering campus perimeters, corridors, parking, and laboratory entries, backed by vigilant on-site security staff.', 'assets/images/lab-electronics-electrical.jpg', 10, 1),
(11, 'Ramps & Lifts (Barrier-Free Accessibility)', 'ramps-and-lifts', 'Inclusion', 'Accessible infrastructure including ramps, wide doorways, and elevators supporting barrier-free mobility.', 'KCET is committed to universal accessibility, ensuring all students and visitors with diverse physical abilities can navigate academic buildings comfortably through strategically positioned ramps, wide corridors, and elevator access.', 'assets/images/campus-main-block.jpg', 11, 1),
(12, 'Spacious Parking', 'spacious-parking', 'Convenience', 'Organized, safe, and designated vehicle parking zones for staff, visitors, and commuting students.', 'Dedicated parking bays accommodate two-wheelers, faculty automobiles, and college transit vehicles safely inside the campus perimeter under continuous security observation.', 'assets/images/campus-panoramic.jpg', 12, 1);
INSERT INTO notices (id, title, slug, category, summary, content, attachment_file, is_featured, publish_date, expiry_date, status) VALUES
(1, 'Admission Notice for B.Tech Programmes (Session 2026-27)', 'admission-notice-b-tech-2026-27', 'admissions', 'Applications are invited from eligible candidates for 4-year B.Tech programmes in AI, Computer, Civil, IT, and ECE.', 'Kashmir College of Engineering & Technology (KCET), Ranbirgarh, Srinagar invites online and offline applications for admission into 4-Year B.Tech Programmes for the Academic Session 2026-27. Candidates who have passed 10+2 with Physics and Mathematics alongside Chemistry/Computer Science with minimum 45% marks (40% for reserved category) are eligible to apply. Merit scholarships are available for high performers.', 'assets/files/admission-notice-2026.pdf', 1, '2026-03-01', '2026-08-31', 'published'),
(2, 'Lateral Entry Admissions Notice (Direct 3rd Semester Admission)', 'lateral-entry-admissions-notice-2026', 'admissions', 'Diploma and B.Sc graduates are eligible for direct admission to 2nd year (3rd semester) B.Tech engineering.', 'KCET invites applications for Lateral Entry into the 3rd Semester of B.Tech for candidates possessing a 3-Year Engineering Diploma in relevant branches or B.Sc with Mathematics. Seats are available across all engineering departments.', 'assets/files/lateral-entry-2026.pdf', 1, '2026-03-10', '2026-08-31', 'published'),
(3, 'Technical Boot Camp 2026: Hands-on AI & Full-Stack Development', 'technical-boot-camp-2026', 'academics', 'A 5-day intensive technical boot camp focusing on modern web stacks, deep learning models, and cloud deployment.', 'The Departments of Computer Engineering and Artificial Intelligence are jointly hosting a 5-day Hands-on Technical Boot Camp for second and third-year engineering students. Eminent industry mentors will lead workshops on Next-Gen APIs, containerization, and PyTorch.', NULL, 1, '2026-04-05', '2026-05-01', 'published'),
(4, 'Semester Examination Notification & Form Submission Schedule', 'semester-examination-schedule-spring-2026', 'examinations', 'Notification regarding the schedule for submission of examination forms and internal assessment deadlines.', 'All students are advised to check the timetable and submit their term examination forms before the scheduled deadline. Admit cards will be issued from the examination office upon clearance of semester dues.', 'assets/files/exam-schedule-2026.pdf', 0, '2026-03-20', '2026-06-30', 'published'),
(5, 'Faculty Recruitment Drive: Assistant Professors & Lab Instructors', 'faculty-recruitment-drive-2026', 'recruitment', 'KCET invites applications from qualified candidates for teaching and laboratory positions in emerging technologies.', 'Applications are invited from dynamic, qualified educators with M.Tech / Ph.D. degrees in Computer Engineering, Artificial Intelligence, and Civil Engineering. Detailed CVs may be submitted through the careers portal or emailed to careers@kcet.edu.in.', 'assets/files/recruitment-notice-2026.pdf', 0, '2026-02-15', '2026-05-15', 'published');
INSERT INTO events (id, title, slug, category, start_date, end_date, location, summary, content, featured_image, status, is_featured) VALUES
(1, 'Inauguration of Kashmir College of Engineering & Technology by Hon\'ble Lt. Governor Sh. Manoj Sinha', 'inauguration-by-honble-lt-governor', 'Institutional Milestone', '2025-05-15', '2025-05-15', 'KCET Campus, Srinagar', 'Hon\'ble Lt. Governor Sh. Manoj Sinha officially inaugurated the sprawling green campus of KCET in Srinagar, highlighting the mission to elevate technical education in J&K.', 'In a landmark ceremony for technical education in Jammu & Kashmir, the Hon\'ble Lieutenant Governor Sh. Manoj Sinha officially inaugurated the campus of Kashmir College of Engineering & Technology at Ranbirgarh, Srinagar. Addressing faculty, students, and dignitaries, the Lt. Governor commended the institution\'s commitment to outcome-based education and state-of-the-art laboratory infrastructure, emphasizing the critical role of young engineering innovators in building regional infrastructure and advancing digital governance across the Union Territory.', 'assets/images/event-inauguration-lg.jpg', 'published', 1),
(2, 'Annual Technical Boot Camp & Innovation Hackathon', 'annual-technical-boot-camp-2026', 'Technical Fest', '2026-04-18', '2026-04-20', 'KCET Multipurpose Hall & AI Lab', 'Engineering scholars from all five B.Tech disciplines collaborated across intensive workshops on applied deep learning, full-stack systems, and IoT.', 'The annual KCET Boot Camp 2026 brought together students from all five engineering branches to collaborate on practical software and hardware projects. Projects ranged from IoT apple orchard monitoring sensors to automated Kashmiri language translation models.', 'assets/images/event-bootcamp.jpg', 'published', 1),
(3, 'Academic Induction & Campus Orientation', 'academic-induction-and-campus-orientation', 'Campus Life', '2026-09-05', '2026-09-05', 'KCET Campus Auditorium', 'Welcoming the new cohort of engineering students across the 100+ kanal green campus with mentorship briefings and lab tours.', 'The college celebrated the arrival of the new engineering cohort with vibrant music, traditional Kashmiri performances, drama sketches, and interactive team-building activities. The Principal and faculty heads addressed the students, urging them to combine academic rigor with ethical integrity.', 'assets/images/campus-main-block.jpg', 'published', 1);
INSERT INTO faqs (id, category, question, answer, display_order, is_active) VALUES
(1, 'admissions', 'What are the basic eligibility criteria for admission into 4-year B.Tech programmes?', 'Candidates must have passed 10+2 (Higher Secondary Part II) or equivalent examination with Physics and Mathematics as compulsory subjects along with Chemistry, Computer Science, or Biology, securing at least 45% aggregate marks (40% for reserved category candidates).', 1, 1),
(2, 'admissions', 'Can Diploma holders apply for direct admission into the 2nd year (Lateral Entry)?', 'Yes, candidates who have successfully completed a 3-Year Engineering Diploma in a relevant engineering discipline or a B.Sc with Mathematics are eligible for direct admission to the 3rd Semester (2nd Year) under the Lateral Entry scheme.', 2, 1),
(3, 'facilities', 'Does the college provide student transport facilities across Srinagar and other districts?', 'Yes, KCET operates an extensive bus fleet connecting Srinagar city, Budgam, Ganderbal, and nearby peripheral routes. Transport passes are issued at the start of each semester.', 3, 1),
(4, 'academics', 'What is the medium of instruction for all engineering courses?', 'The medium of instruction and examination for all B.Tech courses at Kashmir College of Engineering & Technology is strictly English.', 4, 1),
(5, 'facilities', 'Is there hostel accommodation available for students outside Srinagar?', 'KCET assists outstation students in securing verified, comfortable, and safe boarding accommodations near the campus. Please speak to the student welfare desk for current arrangements.', 5, 1),
(6, 'admissions', 'Are scholarships or fee waivers available for meritorious students?', 'Yes, KCET provides merit-based tuition fee concessions for top rankers, underprivileged meritorious students, and special assistance for sports achievers. Details are provided during admission counselling.', 6, 1);
